MOD = 10**9 + 7

def is_good(mask):
    for i in range(1, 10):
        if mask % i != 0:
            return False
    return True

def count_ways(P, T):
    n, m = len(T), len(P)
    dp = [[0] * (1 << 10) for _ in range(m + 1)]
    dp[0][1] = 1

    for i in range(n):
        for mask in range(1 << 10):
            if dp[i][mask] > 0:
                for j in range(m):
                    if T[i] == P[j]:
                        new_mask = mask
                        for k in range(1, 10):
                            if (i + 1) % k == 0:
                                new_mask |= (1 << (k - 1))
                        dp[i + 1][new_mask] = (dp[i + 1][new_mask] + dp[i][mask]) % MOD

    result = 0
    for mask in range(1 << 10):
        if is_good(mask):
            result = (result + dp[n][mask]) % MOD

    return result

# Read input
P = input().strip()
T = input().strip()

# Compute and print the result
print(count_ways(P, T))
